38	/**
39	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
40	 * so tests can assert side-effects by reading that file — the second test-assertion channel
41	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
42	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
43	 *
44	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
45	 * SYNC) so a test reads the record immediately.
46	 */
47	@Service
48	public class Audit {
49	
50	    private final Path file;
51	
52	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
53	        this.file = Path.of(path);
54	    }
55	
56	    /** Append one audit record. Tests assert the exact line(s) in the file. */
57	    public synchronized void record(String entry) {
58	        try {
59	            Path parent = file.toAbsolutePath().getParent();
60	            if (parent != null) {
61	                Files.createDirectories(parent);
62	            }
63	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
64	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
65	        } catch (IOException e) {
66	            throw new UncheckedIOException(e);
67	        }
68	    }
69	
70	    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
71	    public synchronized void clear() {
72	        try {
73	            Files.deleteIfExists(file);
74	        } catch (IOException e) {
75	            throw new UncheckedIOException(e);
76	        }
77	    }
