362	                Map<String, Object> pctDiscount = new HashMap<>(Map.of("pct", i.get("discountPct")));
363	                if (i.get("discountCap") != null) {
364	                    pctDiscount.put("cap", i.get("discountCap"));
365	                }
366	                discounts.add(pctDiscount);
367	            }
368	            if (i.get("discountAmount") != null && new BigDecimal(i.get("discountAmount").toString()).signum() > 0) {
369	                discounts.add(Map.of("amount", i.get("discountAmount")));
370	            }
371	            // An invoice whose fixture says nothing about discounts starts with the client's standard one, as a
372	            // newly raised invoice does.
373	            BigDecimal clientDefaultPct = decimal(client.get("DEFAULT_DISCOUNT_PCT"));
374	            if (i.get("discounts") == null && i.get("discountPct") == null && i.get("discountAmount") == null
375	                    && clientDefaultPct.signum() > 0) {
376	                discounts.add(Map.of("pct", clientDefaultPct));
377	            }
378	            // The percentages each take their share of the subtotal (never more than is left); the flat
379	            // amounts are then taken off what is left and shared across the lines in proportion to what
380	            // each charges.
381	            // Each line is first taken down by its own discount, if it has one.
382	            List<BigDecimal> lines = lineItems.stream().map(l -> {
383	                BigDecimal gross = new BigDecimal(l.get("qty").toString())
384	                        .multiply(new BigDecimal(l.get("unitPrice").toString())).setScale(2, RoundingMode.HALF_UP);
385	                return gross.subtract(gross.multiply(lineDiscountPct(l)).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP));
386	            }).toList();
387	            BigDecimal subtotal = lines.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
388	            // A percentage whose cap limits it is shared across the lines like a flat amount; the others are
389	            // taken off each line as a percentage.
390	            BigDecimal discountPct = BigDecimal.ZERO;
391	            BigDecimal cappedDiscount = BigDecimal.ZERO.setScale(2);
392	            BigDecimal left = subtotal;
393	            for (Map<String, Object> d : discounts) {
394	                if (decimal(d.get("pct")).signum() > 0) {
395	                    BigDecimal share = subtotal.multiply(decimal(d.get("pct"))).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
396	                    boolean capped = d.get("cap") != null && share.compareTo(decimal(d.get("cap"))) > 0;
397	                    BigDecimal taken = (capped ? decimal(d.get("cap")).setScale(2, RoundingMode.HALF_UP) : share)
398	                            .min(left.max(BigDecimal.ZERO.setScale(2)));
399	                    if (capped) {
400	                        cappedDiscount = cappedDiscount.add(taken);
401	                    } else {
402	                        discountPct = discountPct.add(decimal(d.get("pct")));
403	                    }
