414	            }
415	            BigDecimal flatDiscount = subtotal.subtract(left).subtract(pctDiscount);
416	            BigDecimal sharedDiscount = flatDiscount.add(cappedDiscount);
417	            BigDecimal tax = BigDecimal.ZERO.setScale(2);
418	            BigDecimal levy = BigDecimal.ZERO.setScale(2);
419	            for (int n = 0; n < lineItems.size(); n++) {
