434	            // just the discounted subtotal.
435	            // An early-payment discount offered is just recorded; it does not change the amount owed.
436	            BigDecimal earlyPaymentPct = i.get("earlyPaymentPct") == null ? BigDecimal.ZERO
437	                    : new BigDecimal(i.get("earlyPaymentPct").toString());
