import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** The app-wide settings. */
export interface Settings {
  /** The sales tax percentage a new invoice starts with. */
  defaultTaxPct: number;
  /** The currency foreign invoices are converted into for the business's own totals (read-only). */
  homeCurrency?: string;
}

@Injectable({ providedIn: 'root' })
export class SettingsService {
  private readonly http = inject(HttpClient);

  get(): Observable<Settings> {
    return this.http.get<Settings>('/api/settings');
  }

  update(settings: Settings): Observable<Settings> {
    return this.http.put<Settings>('/api/settings', settings);
  }
}
import { Component, effect, inject, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { SettingsService } from './settings.service';
import { CurrencyRounding } from '../currencies/currency-rounding';

// The app-wide settings: the standard sales tax rate that every new invoice starts with, and how each currency rounds.
@Component({
  selector: 'app-settings',
  imports: [ReactiveFormsModule, CurrencyRounding],
  template: `
    <h1>Settings</h1>
    @if (settings.error()) {
      <p role="alert" data-testid="settings-error">Could not load the settings.</p>
    }
    <form [formGroup]="form" (ngSubmit)="save()" data-testid="settings-form" novalidate>
      <div>
        <label for="settings-default-tax-rate">Default tax rate (%) for new invoices</label>
        <input
          id="settings-default-tax-rate"
          type="number"
          inputmode="decimal"
          min="0"
          max="100"
          step="0.01"
          formControlName="defaultTaxPct"
          data-testid="settings-default-tax-rate"
          [attr.aria-invalid]="showError()"
          [attr.aria-describedby]="showError() ? 'settings-default-tax-rate-error' : null"
        />
        @if (showError()) {
          <p id="settings-default-tax-rate-error" role="alert" data-testid="settings-default-tax-rate-error">
            Enter a percentage from 0 to 100 with at most two decimal places.
          </p>
        }
      </div>
      <button type="submit" data-testid="settings-save" [disabled]="saving()">Save settings</button>
      @if (saved()) {
        <p role="status" data-testid="settings-saved">Settings saved.</p>
      }
      @if (saveError()) {
        <p role="alert" data-testid="settings-save-error">{{ saveError() }}</p>
      }
    </form>
    <app-currency-rounding />
  `,
})
export class SettingsPage {
  private readonly service = inject(SettingsService);

  protected readonly settings = rxResource({ stream: () => this.service.get() });

  protected readonly saving = signal(false);
  protected readonly saved = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    defaultTaxPct: [
      '',
      [Validators.required, Validators.min(0), Validators.max(100), Validators.pattern(/^\d+(\.\d{1,2})?$/)],
    ],
  });

  // Starts the field from the saved rate once the settings load, unless it has already been edited.
  private readonly syncForm = effect(() => {
    if (this.settings.hasValue() && !this.form.dirty) {
      this.form.setValue({ defaultTaxPct: String(this.settings.value().defaultTaxPct) });
    }
  });

  protected showError(): boolean {
    const control = this.form.controls.defaultTaxPct;
    return control.invalid && (control.touched || control.dirty);
  }

  protected save(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saved.set(false);
    this.saveError.set(null);
    const defaultTaxPct = Number(this.form.getRawValue().defaultTaxPct);
    this.service.update({ defaultTaxPct }).subscribe({
      next: (updated) => {
        this.settings.set(updated);
        this.form.reset({ defaultTaxPct: String(updated.defaultTaxPct) });
        this.saving.set(false);
        this.saved.set(true);
      },
      error: () => {
        this.saveError.set('Could not save the settings. Please try again.');
        this.saving.set(false);
      },
    });
  }
}
import { Component, inject, signal } from '@angular/core';
import { DecimalPipe } from '@angular/common';
import { Currency, CurrencyService } from './currency.service';

/** The usual rounding steps: to the cent, to five or ten cents, and so on up to the whole unit. */
const STEPS = [0.01, 0.05, 0.1, 0.25, 0.5, 1];

// How each currency rounds: amounts in a currency are shown rounded to its step, e.g. the nearest five cents.
@Component({
  selector: 'app-currency-rounding',
  imports: [DecimalPipe],
  template: `
    <section aria-labelledby="currency-rounding-heading" data-testid="currency-rounding">
      <h2 id="currency-rounding-heading">Currency rounding</h2>
      <p id="currency-rounding-hint">Amounts in each currency are shown rounded to the nearest multiple of its step.</p>
      @if (service.currencies.error()) {
        <p role="alert" data-testid="currency-rounding-load-error">Could not load the currencies.</p>
      } @else {
        <table data-testid="currency-rounding-table">
          <caption class="visually-hidden">Rounding step for each currency</caption>
          <thead>
            <tr>
              <th scope="col">Currency</th>
              <th scope="col">Symbol</th>
              <th scope="col">Round to</th>
              <th scope="col"><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            @for (c of service.list(); track c.code) {
              <tr [attr.data-testid]="'currency-rounding-row-' + c.code">
                <th scope="row" data-testid="currency-code">{{ c.code }}</th>
                <td data-testid="currency-symbol">{{ c.symbol }}</td>
                <td>
                  <label class="visually-hidden" [for]="'currency-rounding-step-' + c.code">Round {{ c.code }} to</label>
                  <select
                    [id]="'currency-rounding-step-' + c.code"
                    [attr.data-testid]="'currency-rounding-step-' + c.code"
                    aria-describedby="currency-rounding-hint"
                    (change)="choose(c.code, $any($event.target).value)"
                  >
                    @for (step of stepsFor(c); track step) {
                      <option [value]="step" [selected]="step === chosen(c)">{{ step | number: '1.2-2' : 'en-US' }}</option>
                    }
                  </select>
                </td>
                <td>
                  <button
                    type="button"
                    [attr.data-testid]="'currency-rounding-save-' + c.code"
                    [attr.aria-label]="'Save rounding for ' + c.code"
                    [disabled]="busy() === c.code"
                    (click)="save(c)"
                  >
                    Save
                  </button>
                </td>
              </tr>
            }
          </tbody>
        </table>
      }
      @if (saved()) {
        <p role="status" data-testid="currency-rounding-saved">Rounding for {{ saved() }} saved.</p>
      }
      @if (saveError()) {
        <p role="alert" data-testid="currency-rounding-error">{{ saveError() }}</p>
      }
    </section>
  `,
})
export class CurrencyRounding {
  protected readonly service = inject(CurrencyService);

  // Steps picked but not yet saved, by currency code.
  private readonly picked = signal<Record<string, number>>({});
  protected readonly busy = signal<string | null>(null);
  protected readonly saved = signal<string | null>(null);
  protected readonly saveError = signal<string | null>(null);

  protected stepsFor(currency: Currency): number[] {
    return STEPS.includes(currency.roundingStep) ? STEPS : [...STEPS, currency.roundingStep].sort((a, b) => a - b);
  }

  protected chosen(currency: Currency): number {
    return this.picked()[currency.code] ?? currency.roundingStep;
  }

  protected choose(code: string, value: string): void {
    this.picked.update((p) => ({ ...p, [code]: Number(value) }));
  }

  protected save(currency: Currency): void {
    this.busy.set(currency.code);
    this.saved.set(null);
    this.saveError.set(null);
    this.service.changeRounding(currency.code, this.chosen(currency)).subscribe({
      next: (updated) => {
        this.picked.update(({ [updated.code]: _, ...rest }) => rest);
        this.busy.set(null);
        this.saved.set(updated.code);
      },
      error: () => {
        this.saveError.set(`Could not save the rounding for ${currency.code}. Please try again.`);
        this.busy.set(null);
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { Observable, tap } from 'rxjs';

/** A currency clients can be billed in, with the symbol its amounts are shown with and the step they round to. */
export interface Currency {
  code: string;
  symbol: string;
  /** Amounts in this currency are shown rounded to the nearest multiple of this (0.05 for five cents). */
  roundingStep: number;
  /** The number of decimal places amounts in this currency are shown with (0 for yen). */
  decimals: number;
}

@Injectable({ providedIn: 'root' })
export class CurrencyService {
  private readonly http = inject(HttpClient);

  /** The known currencies, loaded once and kept up to date as their rounding is changed. */
  readonly currencies = rxResource({ stream: () => this.http.get<Currency[]>('/api/currencies') });

  readonly list = computed(() => (this.currencies.hasValue() ? this.currencies.value() : []));

  private readonly byCode = computed(() => new Map(this.list().map((c) => [c.code, c])));

  /** The currency with this code, if it is known (and has loaded). */
  find(code: string): Currency | undefined {
    return this.byCode().get(code);
  }

  changeRounding(code: string, roundingStep: number): Observable<Currency> {
    return this.http
      .put<Currency>(`/api/currencies/${encodeURIComponent(code)}/rounding`, { roundingStep })
      .pipe(tap((updated) => this.currencies.update((list) => (list ?? []).map((c) => (c.code === updated.code ? updated : c)))));
  }
}

